/// `Countries`: the table of the countries.
pub struct Countries;

impl Countries {
    /// The countries, as new models (`Countries.All`; the reference keeps one list of models, the
    /// port creates the models per call because models are single-threaded).
    pub fn all() -> Vec<Rc<Country>> {
        get_countries()
            .into_iter()
            .map(|c| {
                Country::new(
                    c.name.to_string(),
                    c.region.to_string(),
                    c.population,
                    c.area,
                    c.density,
                    c.coast,
                    c.migration,
                    c.infant_mortality,
                    c.gdp,
                    c.literacy,
                    c.phones,
                    c.birth,
                    c.death,
                )
            })
            .collect()
    }

    /// The region of every country, in the order of the countries (`Countries.Regions`).
    pub fn regions() -> &'static [String] {
        static REGIONS: OnceLock<Vec<String>> = OnceLock::new();
        REGIONS.get_or_init(|| get_countries().into_iter().map(|c| c.region.to_string()).collect())
    }
}

ferro_markup_type!(static Countries {
    static_properties: [
        // The items of the combo box of the editing template of the region column.
        Regions: ItemsSource { get: || ItemsSource::from_values(Countries::regions().iter().cloned()) },
    ],
});
